try (NativeContext ctx = NativeContext.create(4)) {
    NativeTensorHandle weight = ctx.parameter(4, 3);
    weight.randomize(42L, 0.1f);
    try (NativeTensorHandle batch = ctx.of(new float[]{1f, 2f, 3f}, 1, 3)) {
        long[] stats = ctx.stats();
        System.out.println(stats[0] + " tensors, graph nodes " + ctx.graphSize());
        System.out.println(batch.rank() + " dims, weight norm " + weight.norm());
    }
}

try (NativeContext ctx = NativeContext.create();
     NativeTensorHandle weight = ctx.parameter(3, 2)) {
    weight.randomize(7L, 0.5f);
    weight.fill(0.1f);
    float[] flat = weight.data();
    System.out.println(weight + " -> " + flat.length);
}
